import {ErrorCodes} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionCursor,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import type {
  IncomingMessage as WireIncomingMessage,
  ListSessionsMessage as WireListSessionsMessage,
  OutgoingMessage as WireOutgoingMessage,
  SessionListMessage as WireSessionListMessage,
  SessionSummaryFrame as WireSessionSummaryFrame,
} from './types/messages.js';

// The list_sessions request and session_list reply belong to the wire unions and are exported at the package root.

describe('the conversation list wire types', () => {
  it('exports ListSessionsMessage, SessionSummaryFrame and SessionListMessage on the wire unions and package root', () => {
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 3,
    } satisfies WireSessionSummaryFrame;
    const cursor: SessionCursor = summary;
    const bareRequest: IncomingMessage = {
      type: 'list_sessions',
    } satisfies ListSessionsMessage satisfies WireListSessionsMessage satisfies WireIncomingMessage;
    const pagedRequest: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: summary,
    } satisfies ListSessionsMessage;
    const epochRequest: ListSessionsMessage = {
      type: 'list_sessions',
      before: {updatedAt: 1_700_000_000_000, sessionId: 's0'},
    };
    const reply: OutgoingMessage = {
      type: 'session_list',
      sessions: [summary],
    } satisfies SessionListMessage satisfies WireSessionListMessage satisfies WireOutgoingMessage;

    expect({
      bareType: bareRequest.type,
      pagedBefore: pagedRequest.before,
      epochBefore: epochRequest.before,
      reply,
      cursorSessionId: cursor.sessionId,
      serverErrorCode: ErrorCodes.SERVER_ERROR,
    }).toEqual({
      bareType: 'list_sessions',
      pagedBefore: summary,
      epochBefore: {updatedAt: 1_700_000_000_000, sessionId: 's0'},
      reply: {type: 'session_list', sessions: [summary]},
      cursorSessionId: 's1',
      serverErrorCode: 'SERVER_ERROR',
    });
  });
});

