  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions limits and before cursors and strips unknown fields such as userId', () => {
    const accepted = [
      validateMessage({type: 'list_sessions'}),
      validateMessage({type: 'list_sessions', limit: 0}),
      validateMessage({
        type: 'list_sessions',
        limit: 25,
        before: {updatedAt: '2026-06-01T00:00:00.000Z', sessionId: 's-1', extra: 'ignored'},
        userId: 'u2',
      }),
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: 1_700_000_000_000, sessionId: 'a'.repeat(128)},
      }),
    ];
    const rejected = [
      validateMessage({type: 'list_sessions', limit: 'ten'}),
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', limit: Number.NaN}),
      validateMessage({type: 'list_sessions', before: 'not-an-object'}),
      validateMessage({type: 'list_sessions', before: null}),
      validateMessage({type: 'list_sessions', before: []}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 42}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      }),
      validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '', sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}}),
    ];

    expect({
      accepted,
      allRejected: rejected.every(result => !result.valid && result.error.length > 0),
    }).toEqual({
      accepted: [
        {valid: true, data: {type: 'list_sessions'}},
        {valid: true, data: {type: 'list_sessions', limit: 0}},
        {
          valid: true,
          data: {
            type: 'list_sessions',
            limit: 25,
            before: {updatedAt: '2026-06-01T00:00:00.000Z', sessionId: 's-1'},
          },
        },
        {
          valid: true,
          data: {
            type: 'list_sessions',
            before: {updatedAt: 1_700_000_000_000, sessionId: 'a'.repeat(128)},
          },
        },
      ],
      allRejected: true,
    });
  });
});

