import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type CursorResult = {valid: true; cursor: ListSessionsMessage['before']} | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit, before} = message;
  if (limit !== undefined && !isValidLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const cursorResult = parseCursor(before);
  if (!cursorResult.valid) {
    return cursorResult;
  }

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) {
    frame.limit = limit;
  }
  if (cursorResult.cursor !== undefined) {
    frame.before = cursorResult.cursor;
  }

  return {valid: true, data: frame};
}

function isValidLimit(limit: unknown): limit is number {
  if (typeof limit !== 'number') return false;
  return Number.isInteger(limit) && limit >= 0;
}

function parseCursor(before: unknown): CursorResult {
  if (before === undefined) {
    return {valid: true, cursor: undefined};
  }
  if (!isRecord(before)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const {sessionId, updatedAt} = before;
  if (!isValidCursorSessionId(sessionId)) {
    return {valid: false, error: `list_sessions before.sessionId must be 1-${MAX_SESSION_ID_LENGTH} chars`};
  }
  if (!isValidCursorTimestamp(updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }

  return {
    valid: true,
    cursor: {
      updatedAt,
      sessionId,
    },
  };
}

function isRecord(candidate: unknown): candidate is Record<string, unknown> {
  if (typeof candidate !== 'object' || candidate === null) return false;
  return !Array.isArray(candidate);
}

function isValidCursorSessionId(sessionId: unknown): sessionId is string {
  if (typeof sessionId !== 'string') return false;
  return sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  return Number.isFinite(new Date(updatedAt).getTime());
}

